// redisConnection.ts -- Redis connection facts read from the runtime config store
//
// Auto-generated by datrix-codegen-typescript. Do not edit manually.
//
// Every Redis client this service opens (each cache block's connection, the
// rate-limit module, the cache helpers, the API-key rate-limit store) takes its
// host, port and logical database from the `connections` namespace of
// the runtime config store -- the same client and namespace the database
// connection reads. No environment variable is read at any point.
//
// The config-store client is started once per process
// (`startRedisConnectionConfig`, awaited by `main.ts` before the application
// module is built). A client requested before that start, or a declared
// connection key with no value, throws with the namespace and key it could not
// resolve -- startup fails rather than running without the store a rate limit
// or a cache depends on.

import Redis from 'ioredis';
import { buildClient, RemoteConfigClient } from './remoteConfig';

const CONNECTIONS_NAMESPACE = "connections";

/**
 * The config-store keys naming one Redis connection: a composed URL, or a
 * host/port pair with an optional logical database index (`null` = database 0).
 * `label` names the connection in logs; it is never a value read from the store.
 */
export type RedisConnectionKeys =
  | { readonly label: string; readonly urlKey: string }
  | {
      readonly label: string;
      readonly hostKey: string;
      readonly portKey: string;
      readonly databaseKey: string | null;
    };

/** The Redis connection the service-wide consumers use (rate-limit module, cache helpers). */
export const SERVICE_REDIS_CONNECTION: RedisConnectionKeys = { label: "redis", hostKey: "redis_host", portKey: "redis_port", databaseKey: "redis_database" };

/** Thrown when a Redis connection cannot be resolved from the config store. */
export class RedisConnectionError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'RedisConnectionError';
  }
}

let startedConfigClient: RemoteConfigClient | null = null;
let configClientStart: Promise<void> | null = null;

/**
 * Start the config-store client Redis connection facts are read from.
 *
 * Idempotent: every caller awaits the same start, so the store is read once per
 * process. A failed start is remembered and re-thrown to every later caller --
 * it never degrades into a client with no connection facts.
 */
export function startRedisConnectionConfig(
  configClient: RemoteConfigClient = buildClient(),
): Promise<void> {
  if (configClientStart === null) {
    configClientStart = configClient.start().then(() => {
      startedConfigClient = configClient;
    });
  }
  return configClientStart;
}

function requireStartedConfigClient(label: string): RemoteConfigClient {
  if (startedConfigClient === null) {
    throw new RedisConnectionError(
      `Redis connection '${label}' was requested before its connection facts were ` +
        `loaded from the config store. Await startRedisConnectionConfig() during ` +
        'bootstrap (main.ts does, before the application module is built) before ' +
        'opening a Redis client.',
    );
  }
  return startedConfigClient;
}

/**
 * Open a new Redis client for *keys*, reading its connection facts from the
 * config store's `connections` namespace.
 *
 * @throws {RedisConnectionError} When the config store has not been started.
 * @throws {RemoteConfigError} When a declared key has no value (the message
 *   names the namespace, the key and the source consulted).
 */
export function newRedisClient(keys: RedisConnectionKeys): Redis {
  const configClient = requireStartedConfigClient(keys.label);
  if ('urlKey' in keys) {
    const url = configClient.getString(CONNECTIONS_NAMESPACE, keys.urlKey);
    console.info(`redis_connection_resolved connection=${keys.label} key=${keys.urlKey}`);
    return new Redis(url);
  }
  const host = configClient.getString(CONNECTIONS_NAMESPACE, keys.hostKey);
  const port = configClient.getInt(CONNECTIONS_NAMESPACE, keys.portKey);
  const db =
    keys.databaseKey === null ? 0 : configClient.getInt(CONNECTIONS_NAMESPACE, keys.databaseKey);
  console.info(
    `redis_connection_resolved connection=${keys.label} host_key=${keys.hostKey} ` +
      `port_key=${keys.portKey} db=${db}`,
  );
  return new Redis({ host, port, db });
}
